; CMS-03 exponential decay, RK4, Q2.29, 1280 steps, generated by repsynth.gen.isb.gen_workloads 0.3.0 for bwm. Do not edit.
; assembled after gen/isb/targets/bwm/bwm.cpu.asm
#bank ram
start:
    ld r13, uart_addr(r0)
    ld r12, exit_addr(r0)
    li r5, 1
    li r10, 28
    shl r6, r5, r10        ; r6 = 2^28, rounding term of qmul
    li r7, 29              ; r7 = Q
    shl r2, r5, r7         ; k = ONE
    shl r1, r5, r7         ; y = ONE
    li r3, 349525        ; h6 = round(h / 6) in Q2.29
    li r4, 1280
    li r8, 9
    li r11, 8
loop:
    beq r4, r0, done
    mul r10, r2, r1        ; k1 = -qmul(k, y)
    add r10, r10, r6
    shr r10, r10, r7
    neg r10, r10
    add r9, r10, r0        ; sum = k1
    shr r14, r10, r8       ; k2 = -qmul(k, y + (k1 >> 9))
    add r14, r1, r14
    mul r10, r2, r14
    add r10, r10, r6
    shr r10, r10, r7
    neg r10, r10
    add r9, r9, r10
    add r9, r9, r10        ; sum += 2 k2
    shr r14, r10, r8       ; k3 = -qmul(k, y + (k2 >> 9))
    add r14, r1, r14
    mul r10, r2, r14
    add r10, r10, r6
    shr r10, r10, r7
    neg r10, r10
    add r9, r9, r10
    add r9, r9, r10        ; sum += 2 k3
    shr r14, r10, r11      ; k4 = -qmul(k, y + (k3 >> 8))
    add r14, r1, r14
    mul r10, r2, r14
    add r10, r10, r6
    shr r10, r10, r7
    neg r10, r10
    add r9, r9, r10        ; sum += k4
    mul r9, r3, r9         ; y += (h6 sum + 2^28) >> 29
    add r9, r9, r6
    shr r9, r9, r7
    add r1, r1, r9
    sub r4, r4, r5
    jal r0, loop
done:
    li r9, msg_y
    jal r15, print
    add r9, r1, r0
    jal r15, hex32
    li r9, msg_nl
    jal r15, print
    li r10, 0x5555
    sw r10, 0(r12)
hang:
    jal r0, hang
msg_y:
    #d8 0x64, 0x65, 0x63, 0x61, 0x79, 0x20, 0x79, 0x3d, 0x00
msg_nl:
    #d8 0x0a, 0x00
    #align 32
; print the zero-terminated string at r9; uses r10, r11; returns through r15
print:
    lb r10, 0(r9)
    beq r10, r0, print_end
    sb r10, 0(r13)
    add r9, r9, r5
    jal r0, print
print_end:
    jalr r0, 0(r15)
; print r9 as 8 hexadecimal digits of its low 32 bits (two's complement); uses r10, r11, r14; returns through r15
hex32:
    bge r9, r0, hex_pos
    li r10, 32
    shl r10, r5, r10
    add r9, r9, r10
hex_pos:
    li r14, 28
hex_loop:
    shr r10, r9, r14       ; x >> 4i
    li r11, 4
    add r11, r14, r11
    shr r11, r9, r11       ; x >> 4(i+1)
    li r8, 4
    shl r11, r11, r8
    sub r10, r10, r11      ; nibble
    li r11, 10
    blt r10, r11, hex_digit
    li r11, 87             ; 'a' - 10
    jal r0, hex_out
hex_digit:
    li r11, 48             ; '0'
hex_out:
    add r10, r10, r11
    sb r10, 0(r13)
    beq r14, r0, hex_end
    li r11, 4
    sub r14, r14, r11
    jal r0, hex_loop
hex_end:
    jalr r0, 0(r15)
    #align 64
uart_addr:
    #d64 $le(0x0000000010000000)
exit_addr:
    #d64 $le(0x0000000010100000)
